<template>
  <div class="friends-container">
    <!-- Header مع عنوان وعدد الأصدقاء -->
    <v-container class="friends-header">
      <v-row align="center" justify="space-between">
        <v-col cols="auto">
          <h2 class="text-h5 font-weight-bold primary--text">
            <v-icon large color="primary" class="mr-2">mdi-account-group</v-icon>
            Friends
          </h2>
        </v-col>
        <v-col cols="auto">
          <v-chip 
            :color="onlineCount > 0 ? 'success' : 'grey'"
            text-color="white"
            small
          >
            <v-icon left small>mdi-account</v-icon>
            {{ onlineCount }} online
          </v-chip>
        </v-col>
      </v-row>
    </v-container>

    <!-- شريط البحث المتقدم -->
    <v-container class="search-container">
      <v-row>
        <v-col cols="12">
          <v-text-field
            v-model="searchByName"
            label="Search for friend  ..."
            prepend-inner-icon="mdi-magnify"
            clearable
            outlined
            dense
            rounded
            hide-details
            class="search-field"
            @click:clear="clearSearch"
          ></v-text-field>
        </v-col>
      </v-row>

      <!-- فلاتر سريعة -->
      <v-row v-if="searchByName" class="mt-2">
        <v-col cols="12">
          <v-chip-group active-class="primary--text" column>
            <v-chip
              small
              filter
              outlined
              @click="filterType = 'all'"
              :color="filterType === 'all' ? 'primary' : ''"
            >
              All ({{ filteredFriends.length }})
            </v-chip>
            <v-chip
              small
              filter
              outlined
              color="success"
              @click="filterType = 'online'"
              :class="{ 'active-filter': filterType === 'online' }"
            >
              <v-icon left small>mdi-check-circle</v-icon>
              Online
            </v-chip>
            <v-chip
              small
              filter
              outlined
              color="grey"
              @click="filterType = 'offline'"
              :class="{ 'active-filter': filterType === 'offline' }"
            >
              <v-icon left small>mdi-minus-circle</v-icon>
              Offline 
            </v-chip>
          </v-chip-group>
        </v-col>
      </v-row>
    </v-container>

    <!-- قائمة الأصدقاء -->
    <v-container class="friends-list" fluid>
      <v-row v-if="filteredFriends.length > 0">
        <v-col
          v-for="user in filteredFriends"
          :key="user.id"
          cols="12"
          sm="6"
          md="4"
          lg="3"
        >
          <!-- بطاقة الصديق المحسنة -->
          <v-card
            class="friend-card mx-auto"
            :class="{ 'friend-online': user.status }"
            elevation="4"
            hover
            @click="viewUserProfile(user.id)"
          >
            <!-- صورة الغلاف -->
            <v-img
              :src="getCoverImage(user)"
              height="80"
              
              class="cover-image"
            >
              <v-btn
                v-if="user.status"
                icon
                small
                color="success"
                class="online-indicator"
                absolute
                top
                left
              >
                <v-icon small>mdi-check-circle</v-icon>
              </v-btn>
            </v-img>

            <!-- صورة الملف الشخصي -->
            <div class="profile-section">
              <v-avatar
                size="80"
                class="profile-avatar"
                @click.stop="viewUserProfile(user.id)"
              >
                <v-img
                  :src="getUserImage(user)"
                  :alt="user.name"
                  @error="handleImageError"
                >
                  <template v-slot:placeholder>
                    <v-progress-circular indeterminate size="30" color="primary"></v-progress-circular>
                  </template>
                </v-img>
              </v-avatar>
            </div>

            <!-- معلومات المستخدم -->
            <v-card-text class="user-info text-center">
              <h3 class="text-subtitle-1 font-weight-bold mb-1">{{ user.name }}</h3>
              
              <!-- حالة الاتصال -->
              <v-chip
                :color="user.status ? 'success' : 'grey'"
                :text-color="user.status ? '' : 'white'"
                small
                class="status-chip"
              >
                <v-icon left x-small>
                  {{ user.status ? 'mdi-check-circle' : 'mdi-minus-circle' }}
                </v-icon>
                {{ user.status ? 'online' : 'offline' }}
              </v-chip>

              <!-- آخر نشاط -->
              <p v-if="!user.status && user.lastSeen" class="last-seen mt-2">
                <v-icon x-small color="grey">mdi-clock-outline</v-icon>
                آخر ظهور: {{ formatLastSeen(user.lastSeen) }}
              </p>
            </v-card-text>

            <v-divider></v-divider>

            <!-- أزرار الإجراءات -->
            <v-card-actions class="action-buttons">
              <v-btn
                block
                :color="'primary'"
                @click.stop="createNewMessage(user.id)"
                class="action-btn"
              >
                <v-icon left small>mdi-chat</v-icon>
                Chat
              </v-btn>
              
              <v-btn
                block
                :color="user.status ? 'success' : 'grey'"
                :disabled="!user.status"
                @click.stop="onNavVideoCall(user.id, user.name)"
                class="action-btn mt-1"
              >
                <v-icon left small>mdi-phone</v-icon>
                Video Call
              </v-btn>
            </v-card-actions>

            <!-- قائمة إضافية (ثلاث نقاط) -->
            <v-menu bottom left>
              <template v-slot:activator="{ on, attrs }">
                <v-btn
                  icon
                  small
                  class="more-menu-btn"
                  v-bind="attrs"
                  v-on="on"
                >
                  <v-icon>mdi-dots-vertical</v-icon>
