<script>
import serverUrl from '../../config';
import io from 'socket.io-client';
import { mapActions, mapGetters } from 'vuex';
import * as types from '../../store/types';
import { eventBus } from '../../main';
import moment from 'moment';

export default {
  name: 'FriendsList',

  data() {
    return {
      socket: io(serverUrl, {
        query: { token: localStorage.getItem('token') },
        transports: ['websocket'],
        reconnection: true,
        reconnectionAttempts: 5
      }),
      searchByName: '',
      filterType: 'all', // all, online, offline
      onlineFriends: new Set(),
      loading: false,
      imageErrors: new Set()
    };
  },

  computed: {
    ...mapGetters({
      friends: types.GET_FRIENDS_LIST,
    }),

    // الأصدقاء المصفاة حسب البحث والفلتر
    filteredFriends() {
      let result = [...this.friends];

      // تطبيق البحث
      if (this.searchByName) {
        const searchLower = this.searchByName.toLowerCase();
        result = result.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          (user.email && user.email.toLowerCase().includes(searchLower))
        );
      }

      // تطبيق الفلتر
      if (this.filterType === 'online') {
        result = result.filter(user => user.status);
      } else if (this.filterType === 'offline') {
        result = result.filter(user => !user.status);
      }

      return result;
    },

    // عدد المتصلين
    onlineCount() {
      return this.friends.filter(f => f.status).length;
    },

    // عدد الأصدقاء الكلي
    totalCount() {
      return this.friends.length;
    }
  },

  methods: {
    ...mapActions({
      getFriends: types.GET_FRIENDS_LIST,
      removeFriendAction: types.REMOVE_FRIEND,
      blockUserAction: types.BLOCK_USER
    }),

    // الحصول على صورة المستخدم
    getUserImage(user) {
      if (user.image) {
        return `data:image/PNG;base64,${user.image}`;
      }
      if (user.profileImage) {
        return user.profileImage.startsWith('http') 
          ? user.profileImage 
          : `${serverUrl}/profile-image/${user.profileImage}`;
      }
      // صورة افتراضية مع الأحرف الأولى
      return `https://ui-avatars.com/api/?name=${encodeURIComponent(user.name)}&background=1565C0&color=fff&size=128`;
    },

    // الحصول على صورة الغلاف
    getCoverImage() {
      // يمكن تخصيص صور غلاف حسب حالة المستخدم
      // if (user.status) {
      //   return 'https://images.unsplash.com/photo-1579546929518-9e396f3cc809?w=400';
      // }
      // return 'https://images.unsplash.com/photo-1500462918059-b1a0cb512f1d?w=400';
    },

    // معالجة خطأ الصورة
    handleImageError(event, userId) {
      this.imageErrors.add(userId);
      event.target.src = `https://ui-avatars.com/api/?name=User&background=1565C0&color=fff&size=128`;
    },

    // تنسيق آخر ظهور
    formatLastSeen(date) {
      if (!date) return 'غير معروف';
      moment.locale('ar');
      return moment(date).fromNow();
    },

    // عرض الملف الشخصي
    viewUserProfile(userId) {
      this.$router.push({
        name: 'userProfile',
        params: { id: userId }
      });
    },

    // إنشاء محادثة جديدة
    createNewMessage(id) {
      this.$router.push({
        name: 'private-chat',
        params: { receiverID: id }
      });
    },

    // بدء مكالمة فيديو
    onNavVideoCall(id, name) {
      this.socket.emit('call-request', id);
      
      this.socket.once('start-video', () => {
        this.$router.push({
          name: 'video-call',
          params: { id, name, caller: true }
        });
      });

      // مهلة في حال عدم الرد
      setTimeout(() => {
        this.socket.off('start-video');
      }, 30000);
    },

    // حذف صديق
    async removeFriend(userId) {
      if (confirm('هل أنت متأكد من إزالة هذا الصديق؟')) {
        await this.removeFriendAction(userId);
        this.$toast?.success('تم إزالة الصديق بنجاح');
      }
    },

    // حظر مستخدم
    async blockUser(userId) {
      if (confirm('هل أنت متأكد من حظر هذا المستخدم؟')) {
        await this.blockUserAction(userId);
        this.$toast?.success('تم حظر المستخدم بنجاح');
      }
    },

    // مسح البحث
    clearSearch() {
      this.searchByName = '';
      this.filterType = 'all';
    },

    // البحث عن أصدقاء جدد
    findFriends() {
      this.$router.push({ name: 'find-friends' });
    }
  },

  watch: {
    // مراقبة تغييرات البحث
    searchByName(newVal) {
      if (!newVal) {
        this.filterType = 'all';
      }
    }
  },

  created() {
    // جلب قائمة الأصدقاء
    this.getFriends();

    // استماع للأحداث
    this.socket.on('online-users', (userId) => {
      this.onlineFriends.add(userId);
      this.$store.commit('changeOnlineStatus', {
        status: 'online',
        userId: userId
      });
    });

    this.socket.on('friend-leave2', (userId) => {
      this.onlineFriends.delete(userId);
      this.$store.commit('changeOnlineStatus', {
        status: 'offline',
        userId: userId
      });
    });
  },

  mounted() {
    // استماع لأحداث التنقل
    eventBus.$on('onNavPost', () => {
      this.$router.push('/');
    });
  },

  beforeDestroy() {
    // تنظيف
    this.socket.off('online-users');
    this.socket.off('friend-leave2');
    eventBus.$off('onNavPost');
  }
};
</script>

